// HMAC-SHA256 verification for staging Telegram webhook
// Verifies x-signature header against HMAC_SECRET_STAGING env var

const crypto = require('crypto');
const signature = $input.item.json.headers?.['x-signature'] || $input.item.json.headers?.['x-telegram-signature'] || '';
const hmacSecret = process.env.HMAC_SECRET_STAGING;
const body = JSON.stringify($input.item.json.body || $input.item.json);

if (!hmacSecret) {
  // No secret configured - skip verification in dev mode
  return { json: { ...$input.item.json, hmac_verified: true, skip_verify: true } };
}

const expectedSignature = 'sha256=' + crypto.createHmac('sha256', hmacSecret).update(body).digest('hex');

// Use timingSafeEqual only if both strings have the same length
const isValid = signature.length === expectedSignature.length && 
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature));

if (!isValid && signature) {
  throw new Error('HMAC verification failed - invalid signature');
}

return { json: { ...$input.item.json, hmac_verified: true } };

// Parse Telegram message for order handling

const body = $input.item.json.body || $input.item.json;
const message = body.message || {};
const text = (message.text || '').toLowerCase().trim();
const chatId = message.chat?.id?.toString() || '';
const firstName = message.chat?.first_name || 'there';
const updateId = body.update_id?.toString() || '';

// Order-related keywords
const orderKeywords = ['order', 'buy', 'purchase', 'get proxy', 'want proxy', 'isp', 'residential', 'mobile', 'datacenter'];
const trialKeywords = ['free trial', 'trial', 'free plan', 'try free'];
const statusKeywords = ['status', 'check', 'track', 'where is', 'my order'];
const helpKeywords = ['help', 'menu', 'start', 'hello', 'hi', 'hello'];

const isOrder = orderKeywords.some(k => text.includes(k));
const isTrial = trialKeywords.some(k => text.includes(k));
const isStatus = statusKeywords.some(k => text.includes(k));
const isHelp = helpKeywords.some(k => text.includes(k));

const intent = isOrder ? 'order' : isTrial ? 'free_trial' : isStatus ? 'status' : isHelp ? 'help' : 'unknown';

return {
  json: {
    channel: 'telegram',
    chat_id: chatId,
    user_id: chatId,
    first_name: firstName,
    message: text,
    message_raw: message,
    update_id: updateId,
    intent,
    is_order: isOrder,
    is_trial: isTrial,
    is_status: isStatus,
    is_help: isHelp
  }
};

// Prepare idempotency key with staging prefix
// Uses staging: prefix to avoid collision with prod

const updateId = $input.item.json.update_id || '';
const chatId = $input.item.json.chat_id || '';
const idempotencyKey = `staging:idempotency:telegram:${updateId || chatId}`;

return {
  json: {
    ...$input.item.json,
    idempotency_key: idempotencyKey
  }
};

// Parse LLM response

let content = $input.item.json.choices?.[0]?.message?.content || '';
let parsed = { intent: 'unknown', entities: {} };

try {
  if (typeof content === 'string') {
    content = content.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    parsed = JSON.parse(content);
  }
} catch (e) {
  // Use keyword fallback
  const msg = ($input.item.json.message || '').toLowerCase();
  parsed = {
    intent: msg.includes('order') || msg.includes('buy') ? 'order' : 
           msg.includes('trial') ? 'free_trial' : 
           msg.includes('status') ? 'status' : 
           msg.includes('help') ? 'help' : 'unknown',
    entities: {}
  };
}

return {
  json: {
    ...$input.item.json,
    intent: parsed.intent || 'unknown',
    entities: parsed.entities || {},
    llm_raw: content
  }
};

// Intent switch - route based on LLM-parsed intent

const intent = $input.item.json.intent;

return {
  json: {
    ...$input.item.json,
    intent_routed: intent
  }
};

// Generate help menu
const message = `🇳🇬 **Styxproxy Proxy**

I can help you with:

🛒 **Order** — ISP, Residential, Mobile, Datacenter
💳 **Check Status** — Track your order
💰 **Pricing** — See all plans
❓ **Help** — How to get started
🔗 **Free Trial** — Get a free proxy

What would you like to do?`;

return { json: { ...$input.item.json, reply_message: message } };
